// Generated by the Font Editor tab of background_remover.html - edit the glyph map there (c = column, r = row of the 8x16 cells in graphics/fonts/latin_short.png, adv = advance in px)
class EmeraldFont {
  constructor(scene) {
    this.scene = scene;
    this.charWidth = 8;
    this.charHeight = 16;
    this.sheetColumns = 32;

    this.glyphMap = {
      // Row 0
      "/E'/": { c: 12, r: 0, adv: 7 },

      // Row 1
      "/e'/": { c: 22, r: 1, adv: 7 },

      // Row 2
      "&": { c: 26, r: 2 },
      "+": { c: 28, r: 2 },

      // Row 3
      "=": { c: 10, r: 3 },
      ";": { c: 12, r: 3 },

      // Row 5
      "/?/": { c: 2, r: 5, adv: 7 },
      "/!/": { c: 4, r: 5, adv: 6 },

      // Row 8
      "/'e/": { c: 8, r: 8, adv: 6 },
      "<": { c: 10, r: 8 },
      ">": { c: 12, r: 8 },

      // Row 10
      "/re/": { c: 0, r: 10, adv: 9 },
      "0": { c: 2, r: 10 },
      "1": { c: 4, r: 10 },
      "2": { c: 6, r: 10 },
      "3": { c: 8, r: 10 },
      "4": { c: 10, r: 10 },
      "5": { c: 12, r: 10 },
      "6": { c: 14, r: 10 },
      "7": { c: 16, r: 10 },
      "8": { c: 18, r: 10 },
      "9": { c: 20, r: 10 },
      "!": { c: 22, r: 10 },
      "?": { c: 24, r: 10 },
      ".": { c: 26, r: 10 },
      "-": { c: 28, r: 10 },

      // Row 11
      "…": { c: 0, r: 11 },
      "\"": { c: 2, r: 11 },
      "/\"/": { c: 4, r: 11, adv: 7 },
      "'": { c: 6, r: 11 },
      "/'/": { c: 8, r: 11, adv: 6 },
      "/f/": { c: 12, r: 11, adv: 7 },
      "/m/": { c: 10, r: 11, adv: 7 },
      "/p/": { c: 14, r: 11, adv: 8 },
      ",": { c: 16, r: 11 },
      "/": { c: 20, r: 11 },
      "A": { c: 22, r: 11 },
      "B": { c: 24, r: 11 },
      "C": { c: 26, r: 11 },
      "D": { c: 28, r: 11 },
      "E": { c: 30, r: 11 },

      // Row 12
      "F": { c: 0, r: 12 },
      "G": { c: 2, r: 12 },
      "H": { c: 4, r: 12 },
      "I": { c: 6, r: 12 },
      "J": { c: 8, r: 12 },
      "K": { c: 10, r: 12 },
      "L": { c: 12, r: 12 },
      "M": { c: 14, r: 12 },
      "N": { c: 16, r: 12 },
      "O": { c: 18, r: 12 },
      "P": { c: 20, r: 12 },
      "Q": { c: 22, r: 12 },
      "R": { c: 24, r: 12 },
      "S": { c: 26, r: 12 },
      "T": { c: 28, r: 12 },
      "U": { c: 30, r: 12 },

      // Row 13
      "V": { c: 0, r: 13 },
      "W": { c: 2, r: 13 },
      "X": { c: 4, r: 13 },
      "Y": { c: 6, r: 13 },
      "Z": { c: 8, r: 13 },
      "a": { c: 10, r: 13 },
      "b": { c: 12, r: 13 },
      "c": { c: 14, r: 13 },
      "d": { c: 16, r: 13 },
      "e": { c: 18, r: 13 },
      "f": { c: 20, r: 13 },
      "g": { c: 22, r: 13 },
      "h": { c: 24, r: 13 },
      "i": { c: 26, r: 13 },
      "j": { c: 28, r: 13 },
      "k": { c: 30, r: 13 },

      // Row 14
      "l": { c: 0, r: 14 },
      "m": { c: 2, r: 14 },
      "n": { c: 4, r: 14 },
      "o": { c: 6, r: 14 },
      "p": { c: 8, r: 14 },
      "q": { c: 10, r: 14 },
      "r": { c: 12, r: 14 },
      "s": { c: 14, r: 14 },
      "t": { c: 16, r: 14 },
      "u": { c: 18, r: 14 },
      "v": { c: 20, r: 14 },
      "w": { c: 22, r: 14 },
      "x": { c: 24, r: 14 },
      "y": { c: 26, r: 14 },
      "z": { c: 28, r: 14 },

      // Row 15
      ":": { c: 0, r: 15 },
      "Ä": { c: 2, r: 15 },
      "Ö": { c: 4, r: 15 },
      "Ü": { c: 6, r: 15 },
      "ä": { c: 8, r: 15 },
      "ö": { c: 10, r: 15 },
      "ü": { c: 12, r: 15 },

      // Row 16
      "/up/": { c: 0, r: 16, w: 2, adv: 11 },
      "/down/": { c: 2, r: 16, w: 2, adv: 11 },
      "/left/": { c: 4, r: 16, w: 2, adv: 10 },
      "/right/": { c: 6, r: 16, w: 2, adv: 11 },
      "Lv": { c: 10, r: 16, w: 2, adv: 11 },
      "PP": { c: 12, r: 16, w: 2, adv: 11 },
      "ID": { c: 14, r: 16, adv: 9 },
      "№": { c: 16, r: 16, w: 2, adv: 11 },
      "_": { c: 18, r: 16, w: 2, adv: 11 },
      "①": { c: 20, r: 16, w: 2, adv: 11 },
      "②": { c: 22, r: 16, w: 2, adv: 11 },
      "③": { c: 24, r: 16, w: 2, adv: 11 },
      "④": { c: 26, r: 16, w: 2, adv: 11 },
      "⑤": { c: 28, r: 16, w: 2, adv: 11 },
      "⑥": { c: 30, r: 16, w: 2, adv: 11 },

      // Row 17
      "⑦": { c: 0, r: 17, w: 2, adv: 11 },
      "⑧": { c: 2, r: 17, w: 2, adv: 11 },
      "⑨": { c: 4, r: 17, w: 2, adv: 11 },
      "(": { c: 6, r: 17 },
      ")": { c: 8, r: 17 },
      "■": { c: 10, r: 17, w: 2, adv: 10 },
      "▲": { c: 12, r: 17, w: 2, adv: 10 },
      "✖": { c: 14, r: 17, w: 2, adv: 10 },
    };
  }

  ensureTexture() {
    // 1. If Phaser already has 'emerald_font' registered in this scene, we're good
    if (this.scene.textures.exists('emerald_font')) return true;

    // 2. If 'latin_short' was loaded by BattleScene or elsewhere, build 'emerald_font' from it instantly
    if (this.scene.textures.exists('latin_short')) {
      const sourceImage = this.scene.textures.get('latin_short').getSourceImage();
      return this._buildCanvasTexture(sourceImage);
    }

    // 3. Otherwise, check global shared image cache
    if (!window._globalEmeraldFontImg) {
      window._globalEmeraldFontImg = new Image();
      window._globalEmeraldFontImg.src = 'graphics/fonts/latin_short.png';
    }

    if (window._globalEmeraldFontImg.complete && window._globalEmeraldFontImg.naturalWidth > 0) {
      return this._buildCanvasTexture(window._globalEmeraldFontImg);
    }

    return false;
  }

  _buildCanvasTexture(sourceImage) {
    if (this.scene.textures.exists('emerald_font')) return true;

    const canvasTex = this.scene.textures.createCanvas('emerald_font', sourceImage.width, sourceImage.height);
    if (!canvasTex) return false;

    canvasTex.draw(0, 0, sourceImage);
    const ctx = canvasTex.context;
    const imgData = ctx.getImageData(0, 0, sourceImage.width, sourceImage.height);
    const data = imgData.data;

    const bgR = data[0];
    const bgG = data[1];
    const bgB = data[2];

    for (let i = 0; i < data.length; i += 4) {
      const r = data[i];
      const g = data[i + 1];
      const b = data[i + 2];

      if ((r === bgR && g === bgG && b === bgB) || (r >= 245 && g >= 245 && b >= 245)) {
        data[i + 3] = 0;
      }
    }

    ctx.putImageData(imgData, 0, 0);
    canvasTex.refresh();

    let frameIndex = 0;
    for (let y = 0; y < sourceImage.height; y += 16) {
      for (let x = 0; x < sourceImage.width; x += 8) {
        canvasTex.add(frameIndex, 0, x, y, 8, 16);
        frameIndex++;
      }
    }
    return true;
  }

  print(startX, startY, text, depth = 11, scale = 2) {
    // If the texture isn't built yet, trigger an async load and auto-redraw when ready
    if (!this.ensureTexture()) {
      if (window._globalEmeraldFontImg && !window._globalEmeraldFontImg.onload) {
        window._globalEmeraldFontImg.onload = () => {
          // Re-trigger print once loaded
          this.print(startX, startY, text, depth, scale);
        };
      }
      return [];
    }

    const createdGlyphs = [];
    let currentX = startX;
    let currentY = startY;
    const strText = String(text);

    let i = 0;
    while (i < strText.length) {
      const char = strText[i];

      if (char === '\n') {
        currentX = startX;
        currentY += 16 * scale; // Scaled line height
        i++;
        continue;
      }

      if (char === ' ') {
        currentX += 5 * scale; // Scaled space width
        i++;
        continue;
      }

      let matchedGlyph = null;
      let matchedTagLength = 0;

      if (char === '/') {
        const closingIndex = strText.indexOf('/', i + 1);
        if (closingIndex !== -1) {
          const potentialTag = strText.substring(i, closingIndex + 1);
          if (this.glyphMap[potentialTag]) {
            matchedGlyph = this.glyphMap[potentialTag];
            matchedTagLength = potentialTag.length;
          }
        }
      }

      if (!matchedGlyph) {
        matchedGlyph = this.glyphMap[char];
        matchedTagLength = 1;
      }

      if (matchedGlyph) {
        const frameIndex = matchedGlyph.r * this.sheetColumns + matchedGlyph.c;
        const cellsW = matchedGlyph.w || 1; // wide glyphs use w cells side by side
        for (let k = 0; k < cellsW; k++) {
          const charImage = this.scene.add.image(currentX + k * 8 * scale, currentY, 'emerald_font', frameIndex + k);
          charImage.setOrigin(0, 0);
          charImage.setDepth(depth);
          charImage.setScale(scale);
          createdGlyphs.push(charImage);
        }
      }

      currentX += (matchedGlyph ? (matchedGlyph.adv != null ? matchedGlyph.adv : ((matchedGlyph.w || 1) > 1 ? matchedGlyph.w * 8 : 6)) : 6) * scale; // glyph advance (adv in the map; default 6, or w*8 for wide glyphs)
      i += matchedTagLength;
    }

    return createdGlyphs;
  }
}
